 auto g=fixture();auto templates=track_templates(g);assert(templates.size()==1&&templates[0].source_prop==0&&templates[0].native_id==42);auto duplicate=g.props[0];duplicate.id=43;duplicate.transform=translate({40,0,0});g.props.push_back(duplicate);auto mesh=g.meshes[0];mesh.prop_index=1;mesh.transform=duplicate.transform;g.meshes.push_back(mesh);g.triangles++;assert(track_templates(g).size()==1);
 const auto original=g.props[0];assert(apply_track_document(g,d)==1);assert(g.props.size()==3&&g.meshes.size()==3&&g.triangles==3);auto&p=g.props.back();assert(p.id!=42&&p.id!=43&&near(p.mass,12)&&near(p.restitution,.3f)&&near(p.inertia.z,4)&&near(p.half.y,2)&&near(p.center.x,.1f));assert(g.props[0].transform==original.transform);assert(near(p.transform[12],100)&&near(p.transform[13],5)&&near(p.transform[14],200));auto expected=multiply(translate({100,5,200}),rotate_y(1.5f));for(int k=0;k<16;k++)assert(near(p.transform[k],expected[k]));assert(g.meshes.back().vertices.size()==3&&g.meshes.back().indices==g.meshes[0].indices&&g.meshes.back().material==g.meshes[0].material&&g.meshes.back().prop_index==2);auto transformed=point(expected,{1,0,0});auto got=point(g.meshes.back().transform,g.meshes.back().vertices[0].position);assert(near(got.x,transformed.x)&&near(got.z,transformed.z));
 auto invalid=d;invalid.placements.push_back({999,{1,2,3},0});size_t before=g.props.size();rejects([&]{apply_track_document(g,invalid);});assert(g.props.size()==before);invalid=d;invalid.stage="other";rejects([&]{apply_track_document(g,invalid);});
 auto route=track_route_json(d);assert(route["available"]==true&&route["points"][0]==Json::array({100.f,3.f,100.f}));assert(route["gates"].size()==4&&route["gates"][0].contains("left")&&route["gates"][0].contains("right"));auto open=d;open.closed=false;assert(!track_route_json(open)["available"].get<bool>());
 auto m=make_track_minimap(d,256);assert(m.bmp[0]=='B'&&m.bmp[1]=='M'&&m.bmp.size()==54+256*256*3);assert(near(m.world_bottom_right.x-m.world_top_left.x,m.world_bottom_right.z-m.world_top_left.z));for(auto p:d.route){assert(p.x>m.world_top_left.x&&p.x<m.world_bottom_right.x&&p.z>m.world_top_left.z&&p.z<m.world_bottom_right.z);}float extent=m.world_bottom_right.x-m.world_top_left.x;auto start=d.route[d.start_index];int x=int(std::lround((start.x-m.world_top_left.x)/extent*255)),y=int(std::lround((start.z-m.world_top_left.z)/extent*255));size_t at=54+(255-y)*256*3+x*3;assert(m.bmp[at]==0x79&&m.bmp[at+1]==0xe8&&m.bmp[at+2]==0x42);assert(m.metadata["WorldTopLeft"].at("1")==m.world_top_left.x);assert(m.tga.size()==18+256*256*4&&m.tga[2]==2&&m.tga[16]==32&&m.tga[17]==8);size_t ta=18+(255-y)*256*4+x*4;assert(m.tga[ta]==0x79&&m.tga[ta+1]==0xe8&&m.tga[ta+2]==0x42&&m.tga[ta+3]==255);rejects([&]{make_track_minimap(d,1024);});
 auto tmp=fs::temp_directory_path()/"ofo_track_editor_test";fs::remove_all(tmp);assert(!load_track_document(tmp,d.stage));save_track_document(tmp,d);save_track_minimap(tmp,d,256);assert(track_document_json(*load_track_document(tmp,d.stage))==j);assert(track_edit_path(tmp,"../../track").parent_path()==tmp/"track_edits");fs::remove_all(tmp);
